class Employee {
    protected String id;
    protected String name;
    protected double baseSalary;

    public Employee(String id, String name, double baseSalary) {
        this.id = id;
        this.name = name;
        this.baseSalary = baseSalary;
    }

    public double calculatePay() {
        return baseSalary;
    }

    public void displayBadge() {
        System.out.println("[ID: " + id + "] " + name + " | Base Salary: $" + baseSalary);
    }
}

class Developer extends Employee {
    private String programmingLanguage;

    public Developer(String id, String name, double baseSalary, String language) {
        super(id, name, baseSalary);
        this.programmingLanguage = language;
    }

    @Override
    public double calculatePay() {
        // Base salary + $5000 technical skill bonus
        return super.calculatePay() + 5000.0;
    }

    public void writeCode() {
        System.out.println(name + " is writing enterprise code in " + programmingLanguage);
    }
}

public class DevRoleDemo {
    public static void main(String[] args) {
        Developer dev = new Developer("DEV-101", "Marcus Vance", 85000.0, "Java");
        dev.displayBadge();
        System.out.println("Total Annual Pay: $" + dev.calculatePay());
        dev.writeCode();
    }
}

