class Manager extends Employee {
    private int teamSize;

    public Manager(String id, String name, double baseSalary, int teamSize) {
        super(id, name, baseSalary);
        this.teamSize = teamSize;
    }

    @Override
    public double calculatePay() {
        // Base salary + $1000 leadership bonus per team member
        return super.calculatePay() + (teamSize * 1000.0);
    }

    public void conductSprintReview() {
        System.out.println(name + " is conducting sprint review with " + teamSize + " engineers.");
    }
}

class Tester extends Employee {
    private String automationTool;

    public Tester(String id, String name, double baseSalary, String tool) {
        super(id, name, baseSalary);
        this.automationTool = tool;
    }

    public void runTests() {
        System.out.println(name + " executing regression test suite using " + automationTool);
    }
}

public class CompanyRosterDemo {
    public static void main(String[] args) {
        Developer dev = new Developer("EMP-1", "Maya Lin", 90000.0, "Java");
        Manager mgr = new Manager("EMP-2", "David Ross", 110000.0, 8);
        Tester qa = new Tester("EMP-3", "Sarah Connor", 75000.0, "Selenium");

        System.out.println("=== Enterprise Employee Roster ===");
        dev.displayBadge();
        System.out.println("Pay: $" + dev.calculatePay());
        dev.writeCode();

        System.out.println("---------------------------------");
        mgr.displayBadge();
        System.out.println("Pay: $" + mgr.calculatePay());
        mgr.conductSprintReview();

        System.out.println("---------------------------------");
        qa.displayBadge();
        System.out.println("Pay: $" + qa.calculatePay());
        qa.runTests();
    }
}

