class Employee {
    protected String name;
    protected double basePay;

    public Employee(String name, double basePay) {
        this.name = name;
        this.basePay = basePay;
    }

    public double getPay() {
        return basePay;
    }
}

class SalariedEmployee extends Employee {
    public SalariedEmployee(String name, double basePay) {
        super(name, basePay);
    }
}

class CommissionEmployee extends Employee {
    private double sales;
    private double commissionRate;

    public CommissionEmployee(String name, double basePay, double sales, double rate) {
        super(name, basePay);
        this.sales = sales;
        this.commissionRate = rate;
    }

    @Override
    public double getPay() {
        return basePay + (sales * commissionRate);
    }
}

public class Main {
    public static void main(String[] args) {
        Employee[] staff = {
            new SalariedEmployee("Alice", 4000.0),
            new CommissionEmployee("Bob", 2000.0, 50000.0, 0.08)
        };

        for (Employee e : staff) {
            System.out.println(e.name + " Total Pay: $" + e.getPay());
        }
    }
}
